function generate_table_figure_source_map(outputFile)
%GENERATE_TABLE_FIGURE_SOURCE_MAP Rebuild the table/figure source-map XLSX.
%
% Usage:
%   generate_table_figure_source_map
%   generate_table_figure_source_map('/path/to/table_figure_source_map.xlsx')
%
% The workbook is stored in XLSX format for readability. The source data
% are kept here so the documented source map can be regenerated without
% relying on a hand-edited spreadsheet.

if nargin < 1 || isempty(outputFile)
    scriptDir = fileparts(mfilename('fullpath'));
    rootDir = char(java.io.File(fullfile(scriptDir, '..', '..')).getCanonicalPath());
    outputFile = fullfile(rootDir, 'docs', 'table_figure_source_map.xlsx');
end

rows = table_figure_source_map_rows();
outputDir = fileparts(outputFile);
if ~exist(outputDir, 'dir')
    mkdir(outputDir);
end

tmpDir = tempname;
mkdir(tmpDir);
cleanupObj = onCleanup(@() cleanup_temp_dir(tmpDir)); %#ok<NASGU>
csvFile = fullfile(tmpDir, 'table_figure_source_map.csv');
writecell(rows, csvFile);

libreOffice = find_libreoffice();
if ~isempty(libreOffice)
    cmd = sprintf('env -u LD_LIBRARY_PATH %s --headless --convert-to xlsx --outdir %s %s', ...
        shell_quote(libreOffice), shell_quote(tmpDir), shell_quote(csvFile));
    [status, msg] = system(cmd);
    if status == 0
        generated = fullfile(tmpDir, 'table_figure_source_map.xlsx');
        if exist(generated, 'file')
            copyfile(generated, outputFile, 'f');
            normalize_source_map_xlsx(outputFile);
            return
        end
    else
        warning('SourceMap:LibreOfficeFailed', ...
            'LibreOffice conversion failed, falling back to MATLAB writecell: %s', strtrim(msg));
    end
end

writecell(rows, outputFile);
end

