function pathOut = find_libreoffice()
candidates = {'libreoffice', 'soffice'};
pathOut = '';
for i = 1:numel(candidates)
    [status, result] = system(sprintf('command -v %s', candidates{i}));
    if status == 0 && ~isempty(strtrim(result))
        pathOut = strtrim(result);
        return
    end
end
end

function q = shell_quote(s)
q = ['''' strrep(char(s), '''', '''"''"''') ''''];
end

function cleanup_temp_dir(tmpDir)
if exist(tmpDir, 'dir')
    rmdir(tmpDir, 's');
end
end

function normalize_source_map_xlsx(xlsxFile)
% LibreOffice can make tiny platform-dependent width/height changes.
% Normalize the simple sheet layout so regenerated files match the
% maintained workbook layout.
layoutDir = tempname;
mkdir(layoutDir);
cleanupObj = onCleanup(@() cleanup_temp_dir(layoutDir)); %#ok<NASGU>
unzip(xlsxFile, layoutDir);

sheetFile = fullfile(layoutDir, 'xl', 'worksheets', 'sheet1.xml');
txt = fileread(sheetFile);
cols = ['<cols>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="1" min="1" style="0" width="9.14"/>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="2" min="2" style="0" width="6.57"/>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="3" min="3" style="0" width="62.57"/>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="4" min="4" style="0" width="243.15"/>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="5" min="5" style="0" width="247.86"/>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="7" min="6" style="0" width="296.29"/>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="8" min="8" style="0" width="169"/>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="9" min="9" style="0" width="19.29"/>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="10" min="10" style="0" width="18.71"/>' ...
    '<col collapsed="false" customWidth="true" hidden="false" outlineLevel="0" max="11" min="11" style="0" width="67.57"/>' ...
    '</cols>'];
txt = regexprep(txt, '<cols>.*?</cols>', cols);
txt = regexprep(txt, '(<row[^>]*?) ht="[^"]+"', '$1 ht="12.75"');

fid = fopen(sheetFile, 'w');
if fid == -1
    error('Could not write %s.', sheetFile);
end
cleanupFid = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, txt);
clear cleanupFid;

if exist(xlsxFile, 'file')
    delete(xlsxFile);
end
cmd = sprintf('cd %s && zip -qr %s .', shell_quote(layoutDir), shell_quote(xlsxFile));
[status, msg] = system(cmd);
if status ~= 0
    error('Failed to rebuild %s after layout normalization: %s', xlsxFile, strtrim(msg));
end
end
